/*
 * Barrett reciprocals of the P-224 and P-521 primes and group orders, and cczp_mod
 * on them. cczp_mod needs floor(b^(2k) / m) with b = 2^64 and k the number of units
 * in m; the constants once held floor(2^(2 * bitlen) / m), which is only the same
 * thing when the bit length is a multiple of 64, so reducing modulo these moduli
 * looped for about 2^64 iterations. Every constant is checked against Python big
 * integers (2**(128*k) // m), the moduli against `openssl ecparam -name secp224r1`
 * and `secp521r1` (explicit parameters), and cczp_mod results against x % m for
 * x = 0, 1, m - 1, m, m + 1, 2m - 1, m*m - 1, b^(2k) - 1, three random values below
 * m*m and one with the low k + 1 units tiny (forces the borrow in HAC 14.42 step 3).
 * A hang is a failure: the test arms a 60 s alarm.
 *
 * Needs 64-bit cc_unit. Build and run from the repository root (on an aarch64 host
 * add -D__arm64__):
 *   clang -fsanitize=address,undefined -fno-sanitize-recover=all -w \
 *     -Iinclude $(sed -n '/set(corecrypto_sources/,/^)/p' CMakeLists.txt \
 *     | grep 'src/' | tr -d '\t ' | sort -u) tests/standalone/cczp_mod_recip.c \
 *     -o /tmp/cczp_mod_recip && /tmp/cczp_mod_recip
 */
#include <corecrypto/ccec.h>
#include <corecrypto/cczp.h>
#include <corecrypto/private/ccec_extra.h>
#include <signal.h>
#include <stdio.h>
