static void on_alarm(int sig) {
	static const char msg[] = "FAIL: cczp_mod did not return within 60 s\n";
	write(1, msg, sizeof msg - 1);
	_exit(1);
}

int main(void) {
	int failures = 0;
	signal(SIGALRM, on_alarm);

	for (size_t i = 0; i < sizeof(vectors) / sizeof(vectors[0]); i++) {
		ccec_const_cp_t cp = vectors[i].curve == 224 ? ccec_cp_224() : ccec_cp_521();
		const cc_size k = vectors[i].k;
		uint8_t zp_bytes[cczp_size(ccn_sizeof_n(9))];
		memset(zp_bytes, 0, sizeof zp_bytes);
		cczp_t order_zp = (cczp_t)(struct cczp*)zp_bytes;
		const int is_prime = vectors[i].modulus == 'p';

		if (!is_prime) {
			/* the order with its reciprocal, built as ccec_verify does */
			CCZP_N(order_zp) = k;
			memcpy(CCZP_PRIME(order_zp), ccec_cp_o(cp), ccn_sizeof_n((2 * k) + 1));
			order_zp.zp->mod_prime = cczp_mod;
		}
		const cc_unit* modulus = is_prime ? cczp_prime(cp.zp) : ccec_cp_o(cp);
		const cc_unit* stored_recip = is_prime ? cczp_recip(cp.zp) : cczp_recip(order_zp);

		if (memcmp(modulus, vectors[i].m, ccn_sizeof_n(k)) != 0) {
			printf("FAIL P-%u %c: modulus differs from the OpenSSL value\n", vectors[i].curve, vectors[i].modulus);
			failures++;
		}
		if (memcmp(stored_recip, vectors[i].recip, ccn_sizeof_n(k + 1)) != 0) {
			printf("FAIL P-%u %c: stored reciprocal is not floor(b^(2k) / m)\n", vectors[i].curve, vectors[i].modulus);
			failures++;
		}

		for (unsigned c = 0; c < vectors[i].ncases; c++) {
			cc_unit r[9];
			memset(r, 0, sizeof r);
			alarm(60);
			if (is_prime)
				cczp_mod(cp.zp, r, (const cc_unit*)vectors[i].cases[c].x, NULL);
			else
				cczp_mod(order_zp, r, (const cc_unit*)vectors[i].cases[c].x, NULL);
			alarm(0);
			if (memcmp(r, vectors[i].cases[c].expected, ccn_sizeof_n(k)) != 0) {
				printf("FAIL P-%u %c: case %u\n", vectors[i].curve, vectors[i].modulus, c);
				failures++;
			}
		}
	}

	printf("%d failure(s)\n", failures);
	return failures != 0;
}

